      align-items: center;
      gap: 8px;
      background: rgba(86, 32, 193, 0.08);
      color: var(--purple);
      font-size: 0.85rem;
      font-weight: 700;
      padding: 6px 16px;
      border-radius: 100px;
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .section-title {
      font-size: 2.5rem;
      font-weight: 800;
      color: var(--gray-800);
      line-height: 1.15;
      letter-spacing: -0.02em;
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 28px;
    }

    .feature-card {
      background: var(--gray-50);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius-lg);
      padding: 36px 28px;
      transition: all var(--transition);
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow);
      border-color: var(--gray-200);
    }

    .feature-icon {
      width: 52px;
      height: 52px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
