    .feature-card:nth-child(1) .feature-icon { background: rgba(85, 218, 155, 0.15); color: #2FAC6E; }
    .feature-card:nth-child(2) .feature-icon { background: rgba(86, 32, 193, 0.1); color: var(--purple); }
    .feature-card:nth-child(3) .feature-icon { background: rgba(255, 107, 74, 0.1); color: var(--coral); }
