    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
      position: relative;
      z-index: 2;
    }

    .stat-item {
      padding: 24px;
    }

    .stat-number {
      font-size: 3.5rem;
      font-weight: 800;
      color: var(--white);
      line-height: 1;
      margin-bottom: 8px;
      letter-spacing: -0.02em;
