    .course-card:hover .play-icon { opacity: 1; }

    .course-info {
      padding: 20px;
    }

    .course-info h3 {
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--gray-800);
      line-height: 1.4;
      margin-bottom: 10px;
