    .feed-card:nth-child(1) .feed-icon { background: rgba(255, 209, 102, 0.15); color: #D4A017; }
    .feed-card:nth-child(2) .feed-icon { background: rgba(86, 32, 193, 0.1); color: var(--purple); }
    .feed-card:nth-child(3) .feed-icon { background: rgba(85, 218, 155, 0.15); color: #2FAC6E; }

