    .teachers-carousel::-webkit-scrollbar { display: none; }

    .teacher-card {
      min-width: 260px;
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius-lg);
      overflow: hidden;
      flex-shrink: 0;
      transition: all var(--transition);
    }

    .teacher-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow);
    }

    .teacher-photo {
      height: 220px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      color: var(--white);
      position: relative;
    }

    .teacher-photo .teacher-initial {
      width: 80px;
      height: 80px;
      border-radius: 50%;
      background: rgba(255,255,255,0.2);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
      font-weight: 800;
    }

    .teacher-info {
      padding: 20px;
    }

    .teacher-info h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--gray-800);
      margin-bottom: 4px;
    }

    .teacher-info p {
      font-size: 0.85rem;
      color: var(--gray-500);
      font-weight: 500;
    }

    .carousel-btn {
