    }

    .carousel-btn:hover { background: var(--gray-50); border-color: var(--gray-300); }

    .carousel-prev { left: -24px; }
    .carousel-next { right: -24px; }

    /* ── TESTIMONIALS ── */
    .testimonials {
      padding: 100px 0;
      background: var(--white);
    }

    .testimonials-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }

    .testimonial-card {
      background: var(--gray-50);
      border: 1px solid var(--gray-100);
